import json
d = json.load(open("/var/tmp/foundry-work/scripts/data.json"))["rows"]

def sse(vmax, km, pts):
    return sum((v - vmax*s/(km+s))**2 for _, s, v in pts)

def fit_full(pts):
    # profile over Km: for given Km, the best Vmax is closed-form (linear LS)
    def best_v(km):
        num = sum(v*s/(km+s) for _, s, v in pts)
        den = sum((s/(km+s))**2 for _, s, v in pts)
        vm = num/den
        return vm, sse(vm, km, pts)
    lo, hi = 1e-3, 1e5
    # log-space golden section on km
    import math
    a, b = math.log(lo), math.log(hi)
    gr = (math.sqrt(5)-1)/2
    c, dd = b - gr*(b-a), a + gr*(b-a)
    for _ in range(300):
        if best_v(math.exp(c))[1] < best_v(math.exp(dd))[1]:
            b = dd
        else:
            a = c
        c, dd = b - gr*(b-a), a + gr*(b-a)
    km = math.exp((a+b)/2)
    vm, s = best_v(km)
    return vm, km, s

def fit_km_only(pts, vmax):
    import math
    f = lambda km: sse(vmax, km, pts)
    a, b = math.log(1e-3), math.log(1e5)
    gr = (math.sqrt(5)-1)/2
    c, dd = b - gr*(b-a), a + gr*(b-a)
    for _ in range(300):
        if f(math.exp(c)) < f(math.exp(dd)):
            b = dd
        else:
            a = c
        c, dd = b - gr*(b-a), a + gr*(b-a)
    return math.exp((a+b)/2), f(math.exp((a+b)/2))

res = {}
for c in ["C6", "C7", "C5", "C4", "C8"]:
    vm, km, s = fit_full(d[c])
    res[c] = (vm, km)
    print(c, "n=%d" % len(d[c]), "Vmax=%.6f" % vm, "Km=%.4f" % km, "SSE=%.3e" % s)
# inhibitor conditions: shared Vmax from matching no-inhibitor condition
for c, ref in [("C1", "C6"), ("C2", "C7"), ("C3", "C7")]:
    vmax = res[ref][0]
    km, s = fit_km_only(d[c], vmax)
    res[c] = (vmax, km)
    print(c, "n=%d" % len(d[c]), "Vmax(shared from %s)=%.6f" % (ref, vmax), "Km_app=%.4f" % km, "SSE=%.3e" % s)
# free fit for reference on inhibitor sets
for c in ["C1", "C2", "C3"]:
    print(c, "free fit:", ["%.5g" % x for x in fit_full(d[c])])
json.dump(res, open("/var/tmp/foundry-work/scripts/res.json", "w"))

